#!/usr/bin/env python3
import html as html_lib
import os
import re
import shutil
import subprocess
import sys
import urllib.request
from pathlib import Path

QUERY = " ".join(sys.argv[1:]).strip()

HOME = Path.home()
ROOT = HOME / ".config" / "opencode"
CACHE = ROOT / "cache"
REPO = CACHE / "zig-upstream"
DOCS_HTML = CACHE / "zig-master.html"
DOCS_TXT = CACHE / "zig-master.txt"

UPSTREAM_URL = os.environ.get("ZIG_UPSTREAM_URL", "https://codeberg.org/ziglang/zig.git")
DOCS_URL = os.environ.get("ZIG_MASTER_DOCS_URL", "https://ziglang.org/documentation/master/")

def run(*cmd):
    p = subprocess.run(cmd, text=True, capture_output=True)
    return p.returncode, p.stdout, p.stderr

def trim(text, limit=14000):
    text = (text or "").strip()
    if len(text) <= limit:
        return text
    return text[:limit] + "\n... [truncated]"

def ensure_cache():
    CACHE.mkdir(parents=True, exist_ok=True)

def ensure_repo():
    ensure_cache()
    try:
        if REPO.exists() and not (REPO / ".git").exists():
            shutil.rmtree(REPO, ignore_errors=True)

        if not (REPO / ".git").exists():
            code, out, err = run("git", "clone", "--depth=1", UPSTREAM_URL, str(REPO))
            if code != 0:
                return False, f"git clone failed\n{trim(err or out, 2000)}"

        code, out, err = run("git", "-C", str(REPO), "fetch", "--depth=1", "origin")
        if code != 0:
            return False, f"git fetch failed\n{trim(err or out, 2000)}"

        code, out, err = run("git", "-C", str(REPO), "checkout", "-f", "FETCH_HEAD")
        if code != 0:
            return False, f"git checkout FETCH_HEAD failed\n{trim(err or out, 2000)}"

        code, out, err = run("git", "-C", str(REPO), "rev-parse", "--short", "HEAD")
        if code != 0:
            return False, f"git rev-parse failed\n{trim(err or out, 2000)}"

        return True, out.strip()
    except Exception as e:
        return False, f"ensure_repo error: {e}"

def refresh_docs():
    ensure_cache()
    with urllib.request.urlopen(DOCS_URL, timeout=30) as r:
        html = r.read().decode("utf-8", "ignore")

    DOCS_HTML.write_text(html, encoding="utf-8")

    # Preserve <pre><code> blocks before tag stripping
    code_blocks = []
    def save_codeblock(m):
        content = m.group(1)
        # Strip syntax-highlighting spans but keep code text
        content = re.sub(r"(?is)<[^>]+>", "", content)
        content = html_lib.unescape(content)
        # remove one leading newline if present
        if content.startswith("\n"):
            content = content[1:]
        # dedent: remove common leading whitespace
        lines = content.split("\n")
        stripped = [l for l in lines if l.strip()]
        if stripped:
            indent = min((len(l) - len(l.lstrip())) for l in lines if l.strip())
            content = "\n".join(l[indent:] for l in lines)
        code_blocks.append(content)
        return f"\x00CODEBLOCK_{len(code_blocks)-1}\x00"

    text = re.sub(r"(?is)<script.*?</script>", " ", html)
    text = re.sub(r"(?is)<style.*?</style>", " ", text)
    # Save <pre><code> blocks
    text = re.sub(r"(?is)<pre[^>]*>\s*<code[^>]*>(.*?)</code>\s*</pre>", save_codeblock, text)
    text = re.sub(r"(?is)<[^>]+>", "\n", text)
    text = html_lib.unescape(text)
    text = re.sub(r"\r\n?", "\n", text)
    text = re.sub(r"[ \t]+", " ", text)
    # Restore code blocks with markdown formatting
    for i, content in enumerate(code_blocks):
        text = text.replace(f"\x00CODEBLOCK_{i}\x00", f"\n```\n{content}\n```\n")
    text = re.sub(r"\n{3,}", "\n\n", text).strip()

    DOCS_TXT.write_text(text, encoding="utf-8")
    return True

def query_tokens(query):
    toks = re.findall(r"[A-Za-z0-9_@.:/-]+", query)
    toks = [t for t in toks if len(t) >= 3]
    if not toks and query.strip():
        toks = [query.strip()]

    # Prioritize tokens that look like code identifiers
    code_toks = [t for t in toks if re.search(r"[A-Z_][a-z]|[a-z][A-Z]|\.zig|\.rs|[A-Z][A-Z]", t)]
    other_toks = [t for t in toks if t not in code_toks]
    # Code-like tokens first, up to 15 total
    return code_toks + other_toks

def build_pattern(tokens):
    if not tokens:
        # Try short substrings of the query instead of the whole thing
        words = re.findall(r"[A-Za-z0-9_@.:/-]+", QUERY)
        words = [w for w in words if len(w) >= 4]
        if words:
            return "|".join(re.escape(w) for w in words)
        return re.escape(QUERY[:80])

    # Use AND for short token lists (more precise), OR for longer ones
    if len(tokens) <= 2:
        return "|".join(re.escape(t) for t in tokens)
    # For 3+ tokens: first 2 are AND-required, rest are optional
    # git grep -E doesn't support AND natively, so use multiple -e args
    # Fallback: return first 2 as stricter pattern
    return "|".join(re.escape(t) for t in tokens)

def search_code(pattern):
    tokens = query_tokens(QUERY)
    try:
        if len(tokens) >= 3:
            # Step 1: wide OR search with all tokens
            or_pattern = "|".join(re.escape(t) for t in tokens[:10])
            rc, out, _ = run("git", "-C", str(REPO), "grep", "-n", "-I", "-E", "-e", or_pattern, "--", "*.zig")
            wide_result = trim(out, 8000) if rc in (0, 1) and (out or "").strip() else None

            if wide_result and out.count("\n") < 200:
                return wide_result

            # Too many results → file-level AND (token[0] in file, token[1] in line)
            rc1, out1, _ = run("git", "-C", str(REPO), "grep", "-l", "-I", "-E", "-e", re.escape(tokens[0]), "--", "*.zig")
            if rc1 not in (0, 1) or not (out1 or "").strip():
                return "No current code hits."
            files_matched = [f.strip() for f in out1.splitlines() if f.strip()]
            if not files_matched:
                return "No current code hits."
            limited = files_matched[:50]
            rc2, out2, _ = run(
                "git", "-C", str(REPO),
                "grep", "-n", "-I", "-E", "-e", re.escape(tokens[1]), "--", *limited
            )
            return trim(out2, 8000) if rc2 in (0, 1) and (out2 or "").strip() else "No current code hits."

        rc, out, err = run("git", "-C", str(REPO), "grep", "-n", "-I", "-E", "-e", pattern, "--", "*.zig")
        return trim(out, 8000) if rc in (0, 1) and (out or "").strip() else "No current code hits."
    except Exception as e:
        return f"code search error: {e}"

def search_diffs(pattern):
    try:
        tokens = query_tokens(QUERY)
        if len(tokens) >= 3:
            key_token = re.escape(tokens[0])
            code, out, err = run(
                "git", "-C", str(REPO),
                "log", "--since=60.days", "--oneline", "-p", "-G", key_token, "--", "*.zig"
            )
            if code not in (0, 1):
                return f"recent diff search failed\n{trim(err or out, 2000)}"
            return trim(out, 8000) if out.strip() else "No recent diff hits."
        else:
            code, out, err = run(
                "git", "-C", str(REPO),
                "log", "--since=60.days", "--oneline", "-p", "-G", pattern, "--", "*.zig"
            )
            if code not in (0, 1):
                return f"recent diff search failed\n{trim(err or out, 2000)}"
            return trim(out, 8000) if out.strip() else "No recent diff hits."
    except Exception as e:
        return f"diff search error: {e}"

def search_docs(tokens):
    try:
        if not DOCS_TXT.exists():
            return "No docs cache yet."

        text = DOCS_TXT.read_text(encoding="utf-8", errors="ignore")
        lines = text.splitlines()

        lower_tokens = [t.lower() for t in tokens[:10]]
        hits = []

        for idx, line in enumerate(lines, start=1):
            low = line.lower()
            if len(lower_tokens) <= 3:
                if any(t in low for t in lower_tokens):
                    hits.append(f"{idx}: {line}")
            else:
                matches = sum(1 for t in lower_tokens if t in low)
                if matches >= 2:
                    hits.append(f"{idx}: {line}")
            if len(hits) >= 100:
                break

        return "\n".join(hits) if hits else "No docs hits."
    except Exception as e:
        return f"docs search error: {e}"

def main():
    if not QUERY:
        print("No query provided.")
        raise SystemExit(1)

    ok, repo_info = ensure_repo()
    if not ok:
        print(repo_info)
        raise SystemExit(2)

    try:
        refresh_docs()
        docs_status = "ok"
    except Exception as e:
        docs_status = f"docs refresh failed: {e}"

    tokens = query_tokens(QUERY)
    pattern = build_pattern(tokens)

    code_hits = search_code(pattern)
    diff_hits = search_diffs(pattern)
    doc_hits = search_docs(tokens)

    print(f"""# zig_upstream

query: {QUERY}
tokens: {", ".join(tokens) if tokens else "(none)"}
repo: {UPSTREAM_URL}
head: {repo_info}
docs: {DOCS_URL}
docs_status: {docs_status}

## CURRENT CODE HITS
{code_hits}

## RECENT DIFF HITS
{diff_hits}

## DOC HITS
{doc_hits}
""")

if __name__ == "__main__":
    main()

